SELECT CUST_INFO_ID, TO_CHAR(SNAPSHOT_DATE, 'MM/DD/YYYY') AS SNAPSHOT_DATE, DAYS_SINCE_LAST_RPC, PTP_RELIABILITY_RATIO, PAYMENT_VELOCITY_30D, PARTIAL_PAYMENT_RATIO, SELF_CURE_HISTORY_FLAG, BOUNCE_RATE_60D, BROKEN_PTP_COUNT_6M, TARGET_WILLINGNESS FROM PIO_COLL_AI_WILLINGNESS_MART WHERE DAY_DATE = TO_DATE(:day_date, 'YYYY-MM-DD')